INSERT INTO essay_rubrics (id, question_id, kunci_jawaban, kata_kunci, rubrik_skor) VALUES
('er-0000003-0000-0000-0000-000000000001', 'q3000002-0000-0000-0000-000000000001', 'User Research adalah proses mengumpulkan dan menganalisis informasi tentang pengguna untuk memahami kebutuhan, perilaku, motivasi, serta masalah yang mereka alami sehingga keputusan desain dapat dibuat berdasarkan data, bukan asumsi.', ARRAY['user research', 'memahami pengguna', 'kebutuhan', 'perilaku', 'data', 'bukan asumsi']::text[], '{"0":"Salah","7":"Ide umum","8":"60% benar","9":"Kurang 1 unsur","10":">=80% kata kunci"}'::jsonb),
('er-0000003-0000-0000-0000-000000000002', 'q3000002-0000-0000-0000-000000000002', 'Riset kualitatif berfokus pada pemahaman mendalam tentang alasan, motivasi, dan perilaku pengguna melalui wawancara atau observasi, sedangkan riset kuantitatif berfokus pada data numerik, statistik, dan pengukuran dalam jumlah besar.', ARRAY['kualitatif', 'alasan', 'motivasi', 'kuantitatif', 'angka', 'statistik']::text[], '{"0":"Salah","7":"Ide umum","8":"60% benar","9":"Kurang 1 unsur","10":">=80% kata kunci"}'::jsonb),
('er-0000003-0000-0000-0000-000000000003', 'q3000002-0000-0000-0000-000000000003', 'Wawancara memungkinkan peneliti memahami kebutuhan, pengalaman, motivasi, dan masalah pengguna secara langsung sehingga menghasilkan insight yang mendalam untuk pengembangan solusi.', ARRAY['wawancara', 'kebutuhan pengguna', 'motivasi', 'masalah', 'insight']::text[], '{"0":"Salah","7":"Ide umum","8":"60% benar","9":"Kurang 1 unsur","10":">=80% kata kunci"}'::jsonb),
('er-0000003-0000-0000-0000-000000000004', 'q3000002-0000-0000-0000-000000000004', 'Leading Question adalah pertanyaan yang secara tidak langsung mengarahkan responden untuk memberikan jawaban tertentu sehingga dapat menimbulkan bias dan mengurangi objektivitas data.', ARRAY['leading question', 'mengarahkan jawaban', 'bias', 'tidak objektif']::text[], '{"0":"Salah","7":"Ide umum","8":"60% benar","9":"Kurang 1 unsur","10":">=80% kata kunci"}'::jsonb),
('er-0000003-0000-0000-0000-000000000005', 'q3000002-0000-0000-0000-000000000005', '5 Whys digunakan untuk menemukan akar penyebab suatu masalah dengan mengajukan pertanyaan "mengapa" secara berulang hingga penyebab mendasarnya ditemukan.', ARRAY['5 whys', 'akar masalah', 'mengapa berulang', 'root cause']::text[], '{"0":"Salah","7":"Ide umum","8":"60% benar","9":"Kurang 1 unsur","10":">=80% kata kunci"}'::jsonb),
('er-0000003-0000-0000-0000-000000000006', 'q3000004-0000-0000-0000-000000000001', 'Empathy Map digunakan untuk memahami perspektif pengguna secara lebih mendalam melalui apa yang mereka katakan, pikirkan, rasakan, lakukan, serta pain dan gain yang mereka miliki.', ARRAY['empathy map', 'memahami pengguna', 'says', 'thinks', 'feels', 'does']::text[], '{"0":"Salah","7":"Ide umum","8":"60% benar","9":"Kurang 1 unsur","10":">=80% kata kunci"}'::jsonb),
('er-0000003-0000-0000-0000-000000000007', 'q3000004-0000-0000-0000-000000000002', 'Says berisi hal-hal yang diucapkan langsung oleh pengguna selama wawancara atau interaksi terkait pengalaman dan kebutuhan mereka.', ARRAY['ucapan', 'pernyataan pengguna', 'hasil wawancara']::text[], '{"0":"Salah","7":"Ide umum","8":"60% benar","9":"Kurang 1 unsur","10":">=80% kata kunci"}'::jsonb),
('er-0000003-0000-0000-0000-000000000008', 'q3000004-0000-0000-0000-000000000003', 'Thinks menggambarkan apa yang dipikirkan pengguna, sedangkan Feels menggambarkan emosi atau perasaan yang dirasakan pengguna terhadap suatu pengalaman atau situasi.', ARRAY['thinks', 'pikiran', 'feels', 'emosi', 'perasaan']::text[], '{"0":"Salah","7":"Ide umum","8":"60% benar","9":"Kurang 1 unsur","10":">=80% kata kunci"}'::jsonb),
('er-0000003-0000-0000-0000-000000000009', 'q3000004-0000-0000-0000-000000000004', 'Pain adalah hambatan, masalah, atau frustrasi yang dialami pengguna, sedangkan Gain adalah manfaat, harapan, atau hasil positif yang ingin dicapai pengguna.', ARRAY['pain', 'masalah', 'hambatan', 'gain', 'manfaat', 'harapan']::text[], '{"0":"Salah","7":"Ide umum","8":"60% benar","9":"Kurang 1 unsur","10":">=80% kata kunci"}'::jsonb),
('er-0000003-0000-0000-0000-000000000010', 'q3000004-0000-0000-0000-000000000005', 'User Persona adalah representasi fiktif dari kelompok pengguna berdasarkan hasil riset yang menggambarkan karakteristik, kebutuhan, tujuan, dan perilaku pengguna.', ARRAY['user persona', 'representasi pengguna', 'fiktif', 'berdasarkan riset', 'karakteristik']::text[], '{"0":"Salah","7":"Ide umum","8":"60% benar","9":"Kurang 1 unsur","10":">=80% kata kunci"}'::jsonb),
('er-0000003-0000-0000-0000-000000000011', 'q3000006-0000-0000-0000-000000000001', 'Karena persona yang dibuat berdasarkan riset mencerminkan kondisi pengguna yang sebenarnya sehingga keputusan desain lebih akurat dan tidak hanya berdasarkan asumsi.', ARRAY['hasil riset', 'akurat', 'bukan asumsi', 'pengguna nyata']::text[], '{"0":"Salah","7":"Ide umum","8":"60% benar","9":"Kurang 1 unsur","10":">=80% kata kunci"}'::jsonb),
('er-0000003-0000-0000-0000-000000000012', 'q3000006-0000-0000-0000-000000000002', 'User Journey Map adalah visualisasi perjalanan pengguna ketika berinteraksi dengan produk atau layanan yang menunjukkan langkah, aktivitas, emosi, dan pain point yang dialami pengguna.', ARRAY['user journey map', 'perjalanan pengguna', 'aktivitas', 'emosi', 'pain point']::text[], '{"0":"Salah","7":"Ide umum","8":"60% benar","9":"Kurang 1 unsur","10":">=80% kata kunci"}'::jsonb),
('er-0000003-0000-0000-0000-000000000013', 'q3000006-0000-0000-0000-000000000003', 'User Journey Map membantu tim memahami pengalaman pengguna secara menyeluruh, menemukan pain point, serta mengidentifikasi peluang perbaikan dan inovasi.', ARRAY['pengalaman pengguna', 'pain point', 'peluang perbaikan', 'inovasi']::text[], '{"0":"Salah","7":"Ide umum","8":"60% benar","9":"Kurang 1 unsur","10":">=80% kata kunci"}'::jsonb),
('er-0000003-0000-0000-0000-000000000014', 'q3000006-0000-0000-0000-000000000004', 'Karena observasi memungkinkan peneliti melihat perilaku pengguna secara langsung sehingga dapat menemukan masalah yang mungkin tidak diungkapkan saat wawancara.', ARRAY['observasi', 'perilaku nyata', 'melihat langsung', 'menemukan masalah']::text[], '{"0":"Salah","7":"Ide umum","8":"60% benar","9":"Kurang 1 unsur","10":">=80% kata kunci"}'::jsonb),
('er-0000003-0000-0000-0000-000000000015', 'q3000006-0000-0000-0000-000000000005', 'Karena data pengguna memberikan gambaran kebutuhan dan masalah yang nyata sehingga solusi yang dibuat lebih relevan, efektif, dan memiliki peluang keberhasilan yang lebih tinggi dibandingkan keputusan yang hanya berdasarkan asumsi.', ARRAY['data pengguna', 'kebutuhan nyata', 'relevan', 'efektif', 'bukan asumsi']::text[], '{"0":"Salah","7":"Ide umum","8":"60% benar","9":"Kurang 1 unsur","10":">=80% kata kunci"}'::jsonb);
